	const insertedRow = {
		id: 'receipt-new-1',
		user_id: 'test-user-id',
		family_id: 'fam-1',
		merchant_name: 'Safeway',
		total_amount: 50.0,
		transaction_date: '2025-12-20',
		receipt_image_path: 'receipts/test.jpg',
		suspicious_date: false
	};

	/**
	 * Point the mocked OCR endpoint at a fixed extract. This is the ONLY OCR touchpoint —
	 * ReceiptService fetches `/api/ocr/extract`; Mistral is never called from tests.
	 */
	function mockOcr(extract: Record<string, unknown>) {
		globalThis.fetch = vi.fn().mockResolvedValue({
			ok: true,
			json: () => Promise.resolve({ data: extract })
		}) as unknown as typeof fetch;
	}

	function makeFile() {
		return new File(['x'], 'receipt.jpg', { type: 'image/jpeg' });
	}

	beforeEach(() => {
		vi.clearAllMocks();

		// Mock Supabase storage upload (returns the storage path implicitly via upload args)
		mockUpload = vi.fn().mockResolvedValue({ error: null });
		(supabase.storage as { from: typeof supabase.storage.from }).from = vi
			.fn()
			.mockReturnValue({ upload: mockUpload }) as unknown as typeof supabase.storage.from;

		// Setup Supabase insert chain: from('receipts').insert(...).select('*').single()
		mockSingle = vi.fn().mockResolvedValue({ data: insertedRow, error: null });
		mockSelect = vi.fn().mockReturnValue({ single: mockSingle });
		mockInsert = vi.fn().mockReturnValue({ select: mockSelect });
		(supabase as { from: typeof supabase.from }).from = vi
			.fn()
			.mockReturnValue({ insert: mockInsert }) as unknown as typeof supabase.from;

		// Reset the shared ExpenseService spies to a known, isolated state each test.
		expenseServiceMock.getVendorRule.mockReset();
		expenseServiceMock.assignCategory.mockReset();
		expenseServiceMock.assignCategory.mockResolvedValue(undefined);

		// Default OCR extract: a merchant name present so the auto-assign path can run.
		mockOcr({ merchant_name: 'Safeway', currency: 'CAD' });
	});

	describe('Requirement 1-3: Check vendor rules after OCR extraction', () => {
		it('should check for vendor rule after OCR extracts merchant name', async () => {
			expenseServiceMock.getVendorRule.mockResolvedValue({
				category_id: 'cat-groceries',
				category_name: 'Groceries'
			});

			await new ReceiptService(supabase).uploadAndCreate(makeFile());

			// Looked up with the inserted row's family_id and the OCR merchant name (verbatim —
			// getVendorRule normalizes internally).
			expect(expenseServiceMock.getVendorRule).toHaveBeenCalledWith('fam-1', 'Safeway');
		});

		it('should auto-assign category when vendor rule matches', async () => {
			mockOcr({ merchant_name: 'Target', currency: 'CAD' });
			expenseServiceMock.getVendorRule.mockResolvedValue({
				category_id: 'cat-shopping',
				category_name: 'Shopping'
			});

			await new ReceiptService(supabase).uploadAndCreate(makeFile());

			// Receipt id from the inserted row, category from the rule, source='auto'.
			expect(expenseServiceMock.assignCategory).toHaveBeenCalledWith(
				'receipt-new-1',
				'cat-shopping',
				'auto'
			);
		});

		it('should NOT auto-assign when no vendor rule exists', async () => {
			expenseServiceMock.getVendorRule.mockResolvedValue(null);

			await expect(
				new ReceiptService(supabase).uploadAndCreate(makeFile())
			).resolves.toBeDefined();

			expect(expenseServiceMock.getVendorRule).toHaveBeenCalledOnce();
			expect(expenseServiceMock.assignCategory).not.toHaveBeenCalled();
		});
	});

	describe('Requirement 4: Handle null / empty merchant name gracefully', () => {
		it('should handle OCR returning null merchant_name without error', async () => {
			mockOcr({ merchant_name: null, currency: 'CAD' });

			await expect(
				new ReceiptService(supabase).uploadAndCreate(makeFile())
			).resolves.toBeDefined();

			// No merchant name → the guard returns before any rule lookup.
			expect(expenseServiceMock.getVendorRule).not.toHaveBeenCalled();
		});

		it('should handle OCR returning empty string merchant_name', async () => {
			mockOcr({ merchant_name: '', currency: 'CAD' });

			await expect(
				new ReceiptService(supabase).uploadAndCreate(makeFile())
			).resolves.toBeDefined();

			// Empty string is falsy → same early return, no lookup with a blank name.
			expect(expenseServiceMock.getVendorRule).not.toHaveBeenCalled();
		});

		it('should NOT auto-assign when the receipt has no family_id (family-scoped)', async () => {
			// Auto-assignment is family-scoped; a row without a family_id must be skipped.
			mockSingle.mockResolvedValue({
				data: { ...insertedRow, family_id: null },
				error: null
			});

			await expect(
				new ReceiptService(supabase).uploadAndCreate(makeFile())
			).resolves.toBeDefined();

			expect(expenseServiceMock.getVendorRule).not.toHaveBeenCalled();
			expect(expenseServiceMock.assignCategory).not.toHaveBeenCalled();
		});
	});

	describe('Requirement 5: Use consistent vendor normalization', () => {
		it('should pass the raw merchant name to getVendorRule (normalization lives there)', async () => {
			mockOcr({ merchant_name: 'SAFEWAY #1234!', currency: 'CAD' });
			expenseServiceMock.getVendorRule.mockResolvedValue({
				category_id: 'cat-groceries',
				category_name: 'Groceries'
			});

			await new ReceiptService(supabase).uploadAndCreate(makeFile());

			// ReceiptService forwards the ORIGINAL merchant name; getVendorRule normalizes it.
			expect(expenseServiceMock.getVendorRule).toHaveBeenCalledWith('fam-1', 'SAFEWAY #1234!');
		});
	});

	describe('Requirement 6: Upload flow triggers auto-assignment', () => {
		it('should auto-assign in the uploadAndCreate flow', async () => {
			expenseServiceMock.getVendorRule.mockResolvedValue({
				category_id: 'cat-groceries',
				category_name: 'Groceries'
			});

			await new ReceiptService(supabase).uploadAndCreate(makeFile());

			expect(expenseServiceMock.assignCategory).toHaveBeenCalledWith(
				'receipt-new-1',
				'cat-groceries',
				'auto'
			);
		});

		// NOTE: the email-ingestion flow lives in supabase/functions/resend/index.ts, not in
		// ReceiptService, so it cannot be exercised through this class. What ReceiptService
		// owns is the guard that keeps the browser upload path from auto-assigning when there
		// is nothing to look up — asserted here as the real, testable behavior.
		it('should not attempt auto-assignment when there is no merchant to match', async () => {
			mockOcr({ currency: 'CAD' }); // no merchant_name key at all

			await expect(
				new ReceiptService(supabase).uploadAndCreate(makeFile())
			).resolves.toBeDefined();

			expect(expenseServiceMock.getVendorRule).not.toHaveBeenCalled();
		});
	});

	describe('Requirement 7-8: Best-effort (non-atomic) assignment and logging', () => {
		// NOTE: the implementation is intentionally NOT atomic — the receipt is inserted first,
		// then the category is assigned as a separate best-effort step afterwards.
		it('should insert the receipt before assigning the category', async () => {
			const order: string[] = [];
			mockInsert.mockImplementation(() => {
				order.push('insert');
				return { select: mockSelect };
			});
			expenseServiceMock.getVendorRule.mockResolvedValue({
				category_id: 'cat-groceries',
				category_name: 'Groceries'
			});
			expenseServiceMock.assignCategory.mockImplementation(() => {
				order.push('assign');
				return Promise.resolve();
			});

			await new ReceiptService(supabase).uploadAndCreate(makeFile());

			expect(order).toEqual(['insert', 'assign']);
		});

		it('should log the auto-assignment event for debugging', async () => {
			const consoleLogSpy = vi.spyOn(console, 'log').mockImplementation(() => {});
			expenseServiceMock.getVendorRule.mockResolvedValue({
				category_id: 'cat-groceries',
				category_name: 'Groceries'
			});

			await new ReceiptService(supabase).uploadAndCreate(makeFile());

			// The impl logs a structured JSON line with event='vendor_rule_auto_assign'.
			const autoAssignLogs = consoleLogSpy.mock.calls.filter(
				(args) => typeof args[0] === 'string' && args[0].includes('vendor_rule_auto_assign')
			);
			expect(autoAssignLogs.length).toBeGreaterThanOrEqual(1);

			consoleLogSpy.mockRestore();
		});
	});

	describe('Integration: Complete upload flow with auto-assignment', () => {
		it('should execute complete flow: upload → OCR → rule check → auto-assign', async () => {
			expenseServiceMock.getVendorRule.mockResolvedValue({
				category_id: 'cat-groceries',
				category_name: 'Groceries'
			});

			const result = await new ReceiptService(supabase).uploadAndCreate(makeFile());

			expect(mockUpload).toHaveBeenCalled();
			expect(mockInsert).toHaveBeenCalled();
			expect(expenseServiceMock.getVendorRule).toHaveBeenCalledWith('fam-1', 'Safeway');
			expect(expenseServiceMock.assignCategory).toHaveBeenCalledWith(
				'receipt-new-1',
				'cat-groceries',
				'auto'
			);
			expect(result.id).toBe('receipt-new-1');
		});
	});

	describe('Edge Cases and Error Handling', () => {
		it('should swallow a getVendorRule failure and still create the receipt', async () => {
			const consoleErrorSpy = vi.spyOn(console, 'error').mockImplementation(() => {});
			expenseServiceMock.getVendorRule.mockRejectedValue(new Error('Database error'));

			// Receipt creation must still succeed — the lookup failure is swallowed.
			const result = await new ReceiptService(supabase).uploadAndCreate(makeFile());

			expect(result.id).toBe('receipt-new-1');
			expect(expenseServiceMock.assignCategory).not.toHaveBeenCalled();
			expect(
				consoleErrorSpy.mock.calls.some(
					(args) => typeof args[0] === 'string' && args[0].includes('Auto-assignment failed')
				)
			).toBe(true);

			consoleErrorSpy.mockRestore();
		});

		it('should swallow an assignCategory failure and still create the receipt', async () => {
			const consoleErrorSpy = vi.spyOn(console, 'error').mockImplementation(() => {});
			expenseServiceMock.getVendorRule.mockResolvedValue({
				category_id: 'cat-groceries',
				category_name: 'Groceries'
			});
			expenseServiceMock.assignCategory.mockRejectedValue(new Error('Category assignment failed'));

			const result = await new ReceiptService(supabase).uploadAndCreate(makeFile());

			// Assignment threw, but the receipt row already exists → upload still succeeds.
			expect(result.id).toBe('receipt-new-1');
			expect(
				consoleErrorSpy.mock.calls.some(
					(args) => typeof args[0] === 'string' && args[0].includes('Auto-assignment failed')
				)
			).toBe(true);

			consoleErrorSpy.mockRestore();
		});

		it('should auto-assign each of several sequential uploads from the same vendor', async () => {
			// The impl has no concurrency-control logic; what we can assert is that repeated
			// uploads of the same vendor each independently trigger an auto-assignment.
			expenseServiceMock.getVendorRule.mockResolvedValue({
				category_id: 'cat-groceries',
				category_name: 'Groceries'
			});

			const service = new ReceiptService(supabase);
			await service.uploadAndCreate(makeFile());
			await service.uploadAndCreate(makeFile());

			expect(expenseServiceMock.assignCategory).toHaveBeenCalledTimes(2);
			expect(expenseServiceMock.assignCategory).toHaveBeenNthCalledWith(
				1,
				'receipt-new-1',
				'cat-groceries',
				'auto'
			);
			expect(expenseServiceMock.assignCategory).toHaveBeenNthCalledWith(
				2,
				'receipt-new-1',
				'cat-groceries',
				'auto'
			);
		});
	});
});
